const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeSambhar = ee.Geometry.Point(75.05, 27.00).buffer(20000); // Buffer a point near Lake Sambhar to cover the lake area

  const dateRange2018_start = '2018-09-15';
  const dateRange2018_end = '2018-10-15';
  const dateRange2019_start = '2019-03-25';
  const dateRange2019_end = '2019-04-25';

  const scale = 30; // Sentinel-2 resolution is 10m for visible/NIR, use a slightly coarser scale for calculations to avoid memory issues with large regions.
  const projection = 'EPSG:32643'; // UTM Zone 43N for Rajasthan, India

  // Function to mask clouds in Sentinel-2 images
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(
                 qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000)
                .select('B.*')
                .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate NDWI and classify water
  function addNdwi(image) {
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI'); // B3=Green, B8=NIR for Sentinel-2
    return image.addBands(ndwi);
  }

  // 2. Data Acquisition & Check
  const s2_2018 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeSambhar)
    .filterDate(dateRange2018_start, dateRange2018_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Pre-filter by cloud percentage
    .map(maskS2clouds)
    .map(addNdwi);

  const s2_2019 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeSambhar)
    .filterDate(dateRange2019_start, dateRange2019_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    .map(maskS2clouds)
    .map(addNdwi);

  const collectionSize2018 = s2_2018.size().getInfo();
  const collectionSize2019 = s2_2019.size().getInfo();

  if (collectionSize2018 === 0 || collectionSize2019 === 0) {
    console.log(`2018 Images: ${collectionSize2018}, 2019 Images: ${collectionSize2019}`);
    console.log("C1");
    return;
  }

  // Get the least cloudy image for each period
  const image2018 = s2_2018.sort('system:cloud_shadow_percentage').first(); // Using cloud_shadow_percentage as proxy for overall clarity after cloud mask
  const image2019 = s2_2019.sort('system:cloud_shadow_percentage').first();

  // Calculate valid pixel count for the region for each image
  const validPixels2018 = image2018.select('NDWI').gt(-999).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeSambhar,
    scale: scale,
    maxPixels: 1e9,
    crs: projection
  }).get('NDWI').getInfo();

  const validPixels2019 = image2019.select('NDWI').gt(-999).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeSambhar,
    scale: scale,
    maxPixels: 1e9,
    crs: projection
  }).get('NDWI').getInfo();

  if (validPixels2018 === 0 || validPixels2019 === 0) {
    console.log(`2018 Valid Pixels: ${validPixels2018}, 2019 Valid Pixels: ${validPixels2019}`);
    console.log("C2");
    return;
  }

  // 3. Processing & Calculation
  // Define a water threshold (adjust if necessary for your region)
  const ndwiThreshold = 0.0;

  const water2018 = image2018.select('NDWI').gt(ndwiThreshold).rename('water');
  const water2019 = image2019.select('NDWI').gt(ndwiThreshold).rename('water');

  // Calculate water area for each image in square meters
  const waterArea2018 = water2018.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeSambhar,
    scale: scale,
    maxPixels: 1e9,
    crs: projection
  }).get('water').getInfo();

  const waterArea2019 = water2019.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeSambhar,
    scale: scale,
    maxPixels: 1e9,
    crs: projection
  }).get('water').getInfo();

  // 4. Validation & Final Answer
  if (waterArea2018 === null || waterArea2019 === null) {
    console.log("C3"); // Calculation resulted in null
    return;
  }

  const area2018_km2 = waterArea2018 / 1e6;
  const area2019_km2 = waterArea2019 / 1e6;

  console.log(`2018 Images: ${collectionSize2018}, Valid Pixels: ${validPixels2018}`);
  console.log(`2019 Images: ${collectionSize2019}, Valid Pixels: ${validPixels2019}`);
  console.log(`Water Area Sep 2018: ${area2018_km2.toFixed(2)} km²`);
  console.log(`Water Area Apr 2019: ${area2019_km2.toFixed(2)} km²`);

  if (area2019_km2 < area2018_km2) {
    console.log("A"); // Yes, surface water extent decreased
  } else {
    console.log("B"); // No, surface water extent did not decrease (it stayed same or increased)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
